package com.crewmoo;

import static org.junit.Assert.assertEquals;

import org.junit.Before;
import org.junit.Test;

public class DialogueTransformerTest {

    private DialogueTransformer transformer;

    @Before
    public void setUp() {
        transformer = new DialogueTransformer(DialogueTransformer.FallbackBehavior.MOO_ALL);
    }

    // --- Punctuation position ---

    @Test
    public void trailingPunctuationOnShortWord() {
        assertEquals("Moo moo!", transformer.transform("Do it!"));
    }

    @Test
    public void interiorPunctuationPreserved() {
        assertEquals("Moo'oo mooo.", transformer.transform("You're dumb."));
    }

    @Test
    public void prefixedPunctuationOnShortWord() {
        assertEquals("Moo 'moo", transformer.transform("Get 'em"));
    }

    @Test
    public void purelyPunctuationUnchanged() {
        assertEquals("...", transformer.transform("..."));
    }

    @Test
    public void pureNumbersUnchanged() {
        assertEquals("moo 10 mooo", transformer.transform("in 10 days"));
    }

    // --- Capitalization ---

    @Test
    public void lowercaseStaysLowercase() {
        assertEquals("moooo", transformer.transform("hello"));
    }

    @Test
    public void titleCasePreserved() {
        assertEquals("Moooo", transformer.transform("Hello"));
    }

    @Test
    public void allCapsPreserved() {
        assertEquals("MOOOO", transformer.transform("HELLO"));
    }

    @Test
    public void singleUpperCharInferredAllCaps() {
        // A lone uppercase letter is detected as all-caps
        assertEquals("MOO", transformer.transform("I"));
    }

    // --- Composite multi-word sentences ---

    @Test
    public void mixedCapsAndPunctuation() {
        assertEquals("MOO moo Moooo moo!", transformer.transform("I am Going to!"));
    }
}

package com.crewmoo;

import java.util.HashMap;
import java.util.Map;
import java.util.function.Supplier;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class DialogueTransformer {

    private static final Pattern WORD_PATTERN = Pattern.compile("\\S+");

    public enum FallbackBehavior {
        ORIGINAL,
        MOO_ALL,
        LONG_MOO;
    }

    private Map<String, String> transformations;
    private Supplier<FallbackBehavior> fallbackBehaviorSupplier;

    public DialogueTransformer() {
        this(FallbackBehavior.ORIGINAL);
    }

    public DialogueTransformer(FallbackBehavior fallbackBehavior) {
        this(() -> fallbackBehavior);
    }

    public DialogueTransformer(Supplier<FallbackBehavior> fallbackBehaviorSupplier) {
        this.fallbackBehaviorSupplier = fallbackBehaviorSupplier;
        this.transformations = new HashMap<>();
    }

    public void registerTransformation(String orig, String replacement) {
        transformations.put(orig, replacement);
    }

    public String transform(String original) {
        return transformations.getOrDefault(original, fallback(original));
    }

    private String fallback(String original) {
        switch (fallbackBehaviorSupplier.get()) {
            case MOO_ALL:
                return mooAllTransform(original);
            case LONG_MOO:
                return longMooTransform(original);
            default:
                return original;
        }
    }

    private String mooAllTransform(String original) {
        return WORD_PATTERN.matcher(original).replaceAll(m -> toMooWord(m.group()));
    }

    private static String toMooWord(String token) {
        // first pass: count letter chars and detect casing
        int letterCount = 0;
        boolean hasLower = false, hasUpper = false;
        char firstLetter = 0;
        for (int i = 0; i < token.length(); i++) {
            char c = token.charAt(i);
            if (Character.isLetter(c)) {
                if (letterCount == 0)
                    firstLetter = c;
                letterCount++;
                if (Character.isLowerCase(c))
                    hasLower = true;
                if (Character.isUpperCase(c))
                    hasUpper = true;
            }
        }
        if (letterCount == 0)
            return token;

        boolean allUpper = hasUpper && !hasLower;
        char m = allUpper || Character.isUpperCase(firstLetter) ? 'M' : 'm';
        char o = allUpper ? 'O' : 'o';
        int mooLen = Math.max(letterCount, 3);

        // Next: Replace letters in-place with moo, preserving non-letter characters
        StringBuilder result = new StringBuilder(token.length() + Math.max(0, 3 - letterCount));
        int mooIdx = 0;
        int lastMooPos = -1;
        for (int i = 0; i < token.length(); i++) {
            if (Character.isLetter(token.charAt(i)) && mooIdx < mooLen) {
                result.append(mooIdx == 0 ? m : o);
                mooIdx++;
                lastMooPos = result.length();
            } else {
                result.append(token.charAt(i));
            }
        }
        // Pad if original word had fewer than 3 letter chars.
        // Insert right after the last moo character so trailing punctuation
        // stays at the edge (e.g. "it!" → "moo!" not "mo!o").
        if (mooIdx < mooLen) {
            StringBuilder padding = new StringBuilder();
            while (mooIdx < mooLen) {
                padding.append(o);
                mooIdx++;
            }
            result.insert(lastMooPos, padding);
        }
        return result.toString();
    }

    private String longMooTransform(String original) {
        // Replace the full string with a single "Moo" of the same length as the
        // original, padding with 'o' as needed.
        StringBuilder moo = new StringBuilder("M");
        for (int i = 1; i < original.length(); i++) {
            moo.append('o');
        }
        if (moo.length() > 0) {
            moo.append('!');
        }
        return moo.toString();
    }
}

